#include <iostream>
#include <array>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<array<long long, 5>> points(n);
    for (auto& point : points) {
        for (long long& coordinate : point) {
            cin >> coordinate;
        }
    }

    if (n > 11) {
        cout << 0 << '\n';
        return 0;
    }

    vector<int> answer;

    for (int i = 0; i < n; ++i) {
        bool good = true;

        for (int j = 0; j < n && good; ++j) {
            if (j == i) continue;

            for (int k = j + 1; k < n; ++k) {
                if (k == i) continue;

                long long dotProduct = 0;
                for (int d = 0; d < 5; ++d) {
                    dotProduct += (points[j][d] - points[i][d]) *
                                  (points[k][d] - points[i][d]);
                }

                if (dotProduct > 0) {
                    good = false;
                    break;
                }
            }
        }

        if (good) {
            answer.push_back(i + 1);
        }
    }

    cout << answer.size() << '\n';
    for (int index : answer) {
        cout << index << '\n';
    }

    return 0;
}

